import numpy as np

def step(point, lr, momentum=0.0, velocity=np.zeros(2)):
    grad = np.array([2 * point[0], 20 * point[1]])
    velocity = momentum * velocity + grad
    return point - lr * velocity, velocity

for momentum in (0.0, 0.9):
    point, velocity = np.array([1.0, 1.0]), np.zeros(2)
    for _ in range(50):
        point, velocity = step(point, 0.05, momentum, velocity)
    print(f'момент {momentum}: {np.round(point, 4)}')

